def score(program: str) -> float:
    if not program:
        return 0.0
    s = sum(map(ord, program)) / len(program)
    v = (s - 55.0) / 40.0
    return max(0.0, min(1.0, v))

def score(program: str) -> float:
    try:
        import ast
        tree = ast.parse(program)
        if any(isinstance(n, ast.FunctionDef) and n.name == "score" 
               for n in ast.walk(tree)):
            return min(1.0, max(0.1, len(program) / 600))
        return 0.0
    except:
        return 0.0

